// The Sidebar's 7 color roles and the Claude Code theme key each draws with
// (MEMORY.md "Sidebar colors inherit the Claude Code theme").
const KEYS = {
  main: 'text',
  muted: 'inactive',
  faint: 'subtle',
  success: 'success',
  warning: 'warning',
  error: 'error',
  accent: 'suggestion',
} as const

export type Role = keyof typeof KEYS
export type Colors = Record<Role, string>

// Each role's color: a selected Theme's override for its key, else the key
// itself, which Claude Code resolves from the person's theme at draw time.
// Under `inherit` there are no overrides.
export const colors = (overrides: Readonly<Record<string, string>> = {}): Colors =>
  Object.fromEntries(Object.entries(KEYS).map(([role, key]) => [role, overrides[key] ?? key])) as Colors

files.hooks/commands.ts:
import type { SidebarId } from '../plugins/plugin'

// What a `/ctui:*` command does (MEMORY.md "`/ctui:*` commands stay quiet on
// success; a bare command opens a picker pane"): write one setting, print one
// line, or open a picker of `options` with `value` selected.
export type Outcome =
  | { text: string }
  | { set: { key: string; value: string | boolean } }
  | { pick: { options: readonly string[]; value?: string } }

export type Toggle = 'enable' | 'disable'

export const NO_CONFIG = "Can't change ctui settings in claude -p. Use /config in an interactive session."

// `/ctui:plugins:enable|disable [plugin]`; `plugins` in registry order.
export function pluginsOutcome(
  action: Toggle,
  args: string,
  plugins: readonly { id: SidebarId; enable: boolean }[],
): Outcome {
  const name = args.trim()
  const on = action === 'enable'
  if (!name) {
    const options = plugins.filter((plugin) => plugin.enable !== on).map((plugin) => plugin.id)
    return options.length ? { pick: { options } } : { text: `All Sidebar plugins are already ${action}d` }
  }
  const plugin = plugins.find((p) => p.id === name)
  if (!plugin) return { text: `Unknown plugin "${name}". Plugins: ${plugins.map((p) => p.id).join(', ')}` }
  if (plugin.enable === on) return { text: `${name} is already ${action}d` }
  return { set: { key: `ctui.${name}_enable`, value: on } }
}

// `/ctui:theme [theme]`: the picker always opens, the current theme selected.
export function themeOutcome(args: string, themes: readonly string[], current: string): Outcome {
  const name = args.trim()
  if (!name) return { pick: { options: themes, value: current } }
  if (!themes.includes(name)) return { text: `Unknown theme "${name}". Themes: ${themes.join(', ')}` }
  if (name === current) return { text: `Sidebar theme is already ${name}` }
  return { set: { key: 'ctui.theme', value: name } }
}

// Gates a write or a picker on the `ctui.theme` `/config` row: `claude -p`
// and the SDK list none, and `$.config.set` throws there.
export const gated = (outcome: Outcome, hasConfig: boolean): Outcome =>
  'text' in outcome || hasConfig ? outcome : { text: NO_CONFIG }

// The line for a `{ deny }` from `$.config.set`.
export function deniedText(set: { key: string; value: string | boolean }, deny: string) {
  const id = /^ctui\.(\w+)_enable$/.exec(set.key)?.[1]
  if (id) return `Can't ${set.value ? 'enable' : 'disable'} ${id}: ${deny}`
  return `Can't switch the Sidebar theme to ${set.value}: ${deny}`
}

files.hooks/config.ts:
import type { PluginOptions } from 'claude-code'

import { plugins } from '../plugins'
import type { SidebarId } from '../plugins/plugin'

// One Sidebar plugin's settings: `<id>_enable`, for a foldable one
// `<id>_folded`, and for `todo` `todo_tools`.
export type SectionConfig = { enable: boolean; folded?: boolean; tools?: boolean }

export type Config = Record<SidebarId, SectionConfig> & {
  agents: SectionConfig & { toasts: boolean }
  todo: SectionConfig & { tools: boolean }
  theme: string
}

// Regroups the flat `userConfig` options (MEMORY.md "Plugin settings are flat
// `userConfig` keys").
export function readConfig(options: PluginOptions): Config {
  const sections = {} as Record<SidebarId, SectionConfig>
  for (const { id } of plugins) {
    const folded = options[`${id}_folded`]
    sections[id] = {
      enable: options[`${id}_enable`] !== false,
      ...(typeof folded === 'boolean' && { folded }),
    }
  }
  return {
    ...sections,
    agents: { ...sections.agents, toasts: options.agents_toasts !== false },
    todo: { ...sections.todo, tools: options.todo_tools !== false },
    theme: typeof options.theme === 'string' ? options.theme : 'inherit',
  }
}

files.hooks/format.ts:
// Pure formatters for the Sidebar's rows (docs/spec/v0.1.md).

const MINUTE = 60_000
const HOUR = 60 * MINUTE
const DAY = 24 * HOUR
const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']

export type Level = 'success' | 'warning' | 'error'

// The role of a bar's fill.
export const level = (percent: number): Level => (percent < 60 ? 'success' : percent < 85 ? 'warning' : 'error')

// `18,402`
export const formatTokens = (tokens: number) => tokens.toLocaleString('en-US')

// `200k`, `1M`
export const formatWindow = (tokens: number) =>
  tokens >= 1_000_000 ? `${+(tokens / 1_000_000).toFixed(1)}M` : `${Math.round(tokens / 1000)}k`

// `$0.21`
export const formatUsd = (usd: number) => `$${usd.toFixed(2)}`

// `resets in 2h 17m`; past a day, `resets in 3d 4h, Mon 09:00` in local 24-hour time.
export function formatReset(resetsAt: string, now: number): string {
  const at = new Date(resetsAt)
  const left = Math.max(at.getTime() - now, 0)
  if (left <= DAY) {
    const hours = Math.floor(left / HOUR)
    const minutes = Math.floor((left % HOUR) / MINUTE)
    return `resets in ${hours ? `${hours}h ` : ''}${minutes}m`
  }
  const pad = (n: number) => String(n).padStart(2, '0')
  const clock = `${WEEKDAYS[at.getDay()]} ${pad(at.getHours())}:${pad(at.getMinutes())}`
  return `resets in ${Math.floor(left / DAY)}d ${Math.floor((left % DAY) / HOUR)}h, ${clock}`
}

// A bar of `width` cells for `percent`: filled `━`, empty `─`. Past 100 it is full.
export function bar(percent: number, width: number): { filled: string; empty: string } {
  const cells = Math.max(width, 0)
  const filled = Math.round((cells * Math.min(Math.max(percent, 0), 100)) / 100)
  return { filled: '━'.repeat(filled), empty: '─'.repeat(cells - filled) }
}

// A percent in the 5 columns right of a bar: `  9%`, ` 100%`.
export const formatPercent = (percent: number) => `${Math.round(percent)}%`.padStart(5)

// `21s`, `1m 15s`, `15m 03s`, `1h 02m`.
export function formatElapsed(ms: number): string {
  const seconds = Math.floor(Math.max(ms, 0) / 1000)
  const pad = (n: number) => String(n).padStart(2, '0')
  if (seconds < 60) return `${seconds}s`
  if (seconds < 3600) return `${Math.floor(seconds / 60)}m ${pad(seconds % 60)}s`
  return `${Math.floor(seconds / 3600)}h ${pad(Math.floor((seconds % 3600) / 60))}m`
}

// MEMORY.md "The turn footer": the mode as Claude Code's pill names it.
const MODES: Record<string, string> = {
  default: 'manual mode',
  acceptEdits: 'accept edits',
  plan: 'plan mode',
  bypassPermissions: 'bypass permissions',
  auto: 'auto mode',
  dontAsk: "don't ask",
}

export const modeLabel = (mode: string) => MODES[mode] ?? mode

// MEMORY.md "The line under the prompt": `claude-opus-5-5 · high effort`, or
// the model alone when it takes no effort (`null`) or none is known.
export const promptLabel = (model: string, effort: string | null | undefined) =>
  effort ? `${model} · ${effort} effort` : model

// The widest pill, `⏵⏵ bypass permissions on`.
const PILL = 24

// The label fits the line beside the pill and the hint, from `columns` wide.
export const fitsPromptLine = (hint: string, label: string, columns: number) =>
  2 + PILL + 1 + hint.length + 2 + label.length <= columns

type Settings = Readonly<Record<string, unknown>>

// `modelSettings[<model>].effortLevel`: the level `/effort` saved for the model.
export const modelEffort = (settings: Settings, model: string): unknown =>
  (settings.modelSettings as Record<string, { effortLevel?: unknown }> | undefined)?.[model]?.effortLevel

// The effort a model starts a session with: its own saved level, else the global one.
export function savedEffort(settings: Settings, model: string): string | undefined {
  const level = modelEffort(settings, model) ?? settings.effortLevel
  return typeof level === 'string' ? level : undefined
}

